import React, { useState } from "react";
import { Link } from "react-router-dom";
import SuperAdminDashboard from "../SuperAdminDashboard";
import "./AdminB.css";

export default function AdminPage() {
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");
  const [error, setError] = useState("");
  const [userRole, setUserRole] = useState(null);

  const handleLogin = (e) => {
    e.preventDefault();
    if (!username.trim() || !password.trim()) {
      setError("Por favor, completa todos los campos.");
      return;
    }

    setError("");

    const lowerUsername = username.toLowerCase();
    if (lowerUsername === "super") {
      setUserRole("super");
    } else if (lowerUsername.includes("ubicacion")) {
      setUserRole("ubicaciones");
    } else if (lowerUsername.includes("proceso")) {
      setUserRole("procesos");
    } else {
      setUserRole("super");
    }

    setIsLoggedIn(true);
  };

  if (!isLoggedIn) {
    return (
      <div className="admin-container">
        <header className="admin-header">
          <div className="header-content">
            <h1 className="header-title">TalkinPon</h1>
            <div className="header-center-text">
              <span>Inicio de sesión.</span>
            </div>
            <Link to="/">
              <img
                src="/university-logo-circular.jpg"
                alt="Logo"
                className="header-logo"
              />
            </Link>
          </div>
        </header>

        <main className="login-main">
          <div className="login-card">
            <h2 className="login-title">Bienvenido Administrador</h2>
            <form onSubmit={handleLogin} className="login-form">
              <div className="form-group">
                <label htmlFor="username">Usuario:</label>
                <input
                  type="text"
                  id="username"
                  value={username}
                  onChange={(e) => {
                    setUsername(e.target.value);
                    setError("");
                  }}
                  placeholder="Ingresa tu usuario..."
                  required
                />
              </div>

              <div className="form-group">
                <label htmlFor="password">Contraseña:</label>
                <input
                  type="password"
                  id="password"
                  value={password}
                  onChange={(e) => {
                    setPassword(e.target.value);
                    setError("");
                  }}
                  placeholder="Ingresa tu contraseña..."
                  required
                />
              </div>

              {error && <div className="error-message">{error}</div>}

              <button type="submit" className="login-button">
                Iniciar sesión
              </button>
            </form>
          </div>
        </main>
      </div>
    );
  }

  if (userRole === "super") {
    return (
      <SuperAdminDashboard
        username={username}
        onLogout={() => {
          setIsLoggedIn(false);
          setUserRole(null);
        }}
      />
    );
  }

  if (userRole === "ubicaciones") {
    return (
      <div className="admin-container">
        <header className="admin-header">
          <div className="header-content">
            <h1 className="header-title">TalkinPon - Admin Ubicaciones</h1>
            <div className="header-buttons">
              <button
                onClick={() => {
                  setIsLoggedIn(false);
                  setUserRole(null);
                }}
                className="logout-btn"
              >
                Cerrar sesión
              </button>
              <Link to="/">
                <img
                  src="/university-logo-circular.jpg"
                  alt="Logo"
                  className="header-logo"
                />
              </Link>
            </div>
          </div>
        </header>

        <main className="admin-main">
          <div className="admin-card">
            <h2 className="admin-welcome">
              Bienvenido Administrador de Ubicaciones, {username}
            </h2>
            <p className="admin-description">
              Gestiona edificios, salones, mapas y ubicaciones del campus universitario.
            </p>

            <div className="admin-grid">
              <div className="admin-option">
                <h3>Gestionar Edificios</h3>
                <p>Agregar, editar o eliminar información de edificios</p>
              </div>
              <div className="admin-option">
                <h3>Actualizar Mapas</h3>
                <p>Subir y actualizar mapas del campus</p>
              </div>
              <div className="admin-option">
                <h3>Rutas y Direcciones</h3>
                <p>Configurar rutas entre ubicaciones</p>
              </div>
              <div className="admin-option">
                <h3>Imágenes de Edificios</h3>
                <p>Gestionar fotos de edificios y salones</p>
              </div>
            </div>
          </div>
        </main>
      </div>
    );
  }

  if (userRole === "procesos") {
    return (
      <div className="admin-container">
        <header className="admin-header">
          <div className="header-content">
            <h1 className="header-title">TalkinPon - Admin Procesos</h1>
            <div className="header-buttons">
              <button
                onClick={() => {
                  setIsLoggedIn(false);
                  setUserRole(null);
                }}
                className="logout-btn"
              >
                Cerrar sesión
              </button>
              <Link to="/">
                <img
                  src="/university-logo-circular.jpg"
                  alt="Logo"
                  className="header-logo"
                />
              </Link>
            </div>
          </div>
        </header>

        <main className="admin-main">
          <div className="admin-card">
            <h2 className="admin-welcome">
              Bienvenido Administrador de Procesos, {username}
            </h2>
            <p className="admin-description">
              Gestiona los procesos administrativos y académicos del sistema.
            </p>

            <div className="admin-grid">
              <div className="admin-option">
                <h3>Kardex</h3>
                <p>Gestionar información de kardex estudiantil</p>
              </div>
              <div className="admin-option">
                <h3>Constancias</h3>
                <p>Administrar emisión de constancias</p>
              </div>
              <div className="admin-option">
                <h3>Titulación</h3>
                <p>Gestionar procesos de titulación</p>
              </div>
              <div className="admin-option">
                <h3>Créditos</h3>
                <p>Administrar créditos académicos</p>
              </div>
              <div className="admin-option">
                <h3>Servicio Social</h3>
                <p>Gestionar servicio social</p>
              </div>
              <div className="admin-option">
                <h3>Residencias</h3>
                <p>Administrar residencias profesionales</p>
              </div>
            </div>
          </div>
        </main>
      </div>
    );
  }

  return null;
}
